-- The grand total an invoice was approved at, when it was over the workspace's approval limit; the
-- approval stands while its grand total is not above it. Null while it has not been approved.
ALTER TABLE invoice ADD COLUMN approved_total DECIMAL(19, 2);
-- The day an invoice was approved; the approval lapses once more than 30 days have passed since then.
-- Null while it has not been approved (or for an approval given before the day was kept).
ALTER TABLE invoice ADD COLUMN approved_on DATE;
-- The most the client may owe, in the client's currency: an invoice that would take its balance over
-- it is not sent. NULL for no limit.
ALTER TABLE client ADD COLUMN credit_limit DECIMAL(19, 2);
-- Whether the client is on hold: their invoices are not sent, their credit is not applied, and their
-- payments pay no invoice but are held as credit.
ALTER TABLE client ADD COLUMN on_hold BOOLEAN DEFAULT FALSE NOT NULL;
